   450  gc_protect(mrb_state *mrb, mrb_gc *gc, struct RBasic *p)
   451  {
   452    if (is_red(p)) return;
   453  #ifdef MRB_GC_FIXED_ARENA
   454    if (gc->arena_idx >= MRB_GC_ARENA_SIZE) {
   455      /* arena overflow error */
   456      gc->arena_idx = MRB_GC_ARENA_SIZE - 4; /* force room in arena */
   457      mrb_exc_raise(mrb, mrb_obj_value(mrb->arena_err));
   458    }
   459  #else
   460    if (gc->arena_idx >= gc->arena_capa) {
   461      /* extend arena */
   462      int newcapa = gc->arena_capa * 3 / 2;
   463      gc->arena = (struct RBasic**)mrb_realloc(mrb, gc->arena, sizeof(struct RBasic*)*newcapa);
   464      gc->arena_capa = newcapa;
   465    }
   466  #endif
   467    gc->arena[gc->arena_idx++] = p;
   468  }
